    private static void verifyOriginals(Path folder,JsonNode manifest)throws Exception{var originals=manifest.path("originals");require(originals.isObject()&&originals.size()>0);var names=new HashSet<String>();originals.fieldNames().forEachRemaining(names::add);try(var paths=Files.list(folder)){require(paths.filter(p->!p.getFileName().toString().equals("manifest.json")).map(p->p.getFileName().toString()).collect(java.util.stream.Collectors.toSet()).equals(names));}for(var it=originals.fields();it.hasNext();){var row=it.next();require(hash(original(folder,row.getKey())).equals(row.getValue().asText()));}}
