    private static byte[] original(Path folder,String name)throws Exception{require(name.matches("[A-Za-z0-9_.-]+"));var p=folder.resolve(name);safeParents(folder);require(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)&&Files.size(p)<=8*1024*1024);return Files.readAllBytes(p);}
